    internal static class Program {
        private const string MutexName = "Local\\HEX_ALERT_CONTROL_CENTER_SINGLE_INSTANCE";
        [STAThread]
        private static void Main(string[] args) {
            bool created;
            using (var mutex = new Mutex(true, MutexName, out created)) {
                if (!created) { MainForm.FocusExisting(); return; }
                Application.EnableVisualStyles();
                Application.SetCompatibleTextRenderingDefault(false);
                Application.ThreadException += (s,e) => { string detail=RedactDiagnostic(e.Exception.ToString());try { var d=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"HexAlert");Directory.CreateDirectory(d);File.AppendAllText(Path.Combine(d,"launcher-errors.log"),DateTime.Now.ToString("s")+" "+detail+Environment.NewLine); } catch {} MessageBox.Show("The launcher encountered an unexpected problem.\n\n"+detail,"HEX ALERT Launcher",MessageBoxButtons.OK,MessageBoxIcon.Error); };
                var window = new MainForm(args.Contains("--start"));
                window.Show();
                Application.Run(window);
                GC.KeepAlive(mutex);
            }
        }
        private static string RedactDiagnostic(string s) { if(s==null)return "";s=Regex.Replace(s,@"(?im)(DISCORD_TOKEN|OPENAI_API_KEY|GEMINI_API_KEY|GROQ_API_KEY|SESSION_SECRET|DASHBOARD_API_KEY|POSTGRES_PASSWORD|DATABASE_URL|AI_ENCRYPTION_KEY)(\s*[=:]\s*)[^\r\n]+","$1$2[REDACTED]");s=Regex.Replace(s,@"(?i)(\b(?:token|api[_ -]?key|secret|password)\b\s*[=:]\s*)[^\s,;]+","$1[REDACTED]");return Regex.Replace(s,@"(?i)Bot\s+[A-Za-z0-9._-]{20,}","Bot [REDACTED]"); }
    }

