        private async Task<string> Run(string file,string args,int timeout=30000){return await Task.Run(()=>{var p=new Process();p.StartInfo=new ProcessStartInfo{FileName=file,Arguments=args,WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};p.Start();var outTask=p.StandardOutput.ReadToEndAsync();var errTask=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(timeout)){try{p.Kill();}catch{}throw new TimeoutException("The operation timed out.");}Task.WaitAll(new Task[]{outTask,errTask},5000);var result=(outTask.Result+"\n"+errTask.Result).Trim();if(p.ExitCode!=0)throw new Exception(Redact(result));return result;});}
