            var pollControl=new NumericUpDown{Minimum=5,Maximum=10,Value=Math.Max(5,Math.Min(10,pollSeconds)),Width=78};
            layout.Controls.Add(open,1,1);layout.Controls.Add(trayCheck,1,2);layout.Controls.Add(auto,1,3);layout.Controls.Add(startup,1,4);
            layout.Controls.Add(pollLabel,0,5);layout.Controls.Add(pollControl,1,5);
            layout.Controls.Add(new Label{Text="TEST_MODE is read from live health. Production Mode is not controlled by the launcher.",AutoSize=true},1,6);
            var shortcut=new Button{Text="Create Desktop Shortcut",Width=190};shortcut.Click+=(s,e)=>CreateDesktopShortcut();layout.Controls.Add(shortcut,1,7);
            var diagnostics=new Button{Text="Technical Details",Width=150};diagnostics.Click+=(s,e)=>ShowDiagnostics();layout.Controls.Add(diagnostics,2,7);
            var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var save=new Button{Text="Save settings",Width=120};
            save.Click+=(s,e)=>{try{if(!File.Exists(Path.Combine(path.Text,".env.example"))||(!File.Exists(Path.Combine(path.Text,"docker-compose.yml"))&&!File.Exists(Path.Combine(path.Text,"compose.yml")))){MessageBox.Show("Select the existing HEX ALERT project folder.");return;}root=Path.GetFullPath(path.Text);openOnStart=open.Checked;minimizeToTray=trayCheck.Checked;autoStart=auto.Checked;pollSeconds=(int)pollControl.Value;poll.Interval=pollSeconds*1000;SaveSettings();SetStartup(startup.Checked);message.Text="Launcher settings saved.";f.Close();}catch(Exception ex){MessageBox.Show(this,"Unable to save launcher settings. "+Redact(ex.Message),"HEX ALERT Launcher",MessageBoxButtons.OK,MessageBoxIcon.Error);}};
            buttons.Controls.Add(save);var cancel=new Button{Text="Cancel",Width=100};cancel.Click+=(s,e)=>f.Close();buttons.Controls.Add(cancel);layout.Controls.Add(buttons,1,8);f.Controls.Add(layout);f.ShowDialog(this);
        }
        private async void ShowDiagnostics(){
            var lines=new List<string>();lines.Add("HEX ALERT Launcher diagnostics");lines.Add("Project: "+root);lines.Add("Launcher: "+Application.ExecutablePath);lines.Add("Windows user: "+Environment.UserDomainName+"\\"+Environment.UserName);lines.Add("TEST_MODE remains controlled by project configuration; launcher production switch is not available.");
            string cli=FindDocker();lines.Add("Docker CLI: "+(cli??"Not found"));lines.Add("Docker Desktop: "+(FindDesktop()??"Not found"));
            if(cli!=null){try{lines.Add("Docker version: "+await Run(cli,"--version",10000));}catch(Exception e){lines.Add("Docker version check: "+Redact(e.Message));}try{lines.Add("Compose version: "+await Run(cli,"compose version --short",10000));}catch(Exception e){lines.Add("Compose check: "+Redact(e.Message));}}
            var h=await Health();lines.Add("Dashboard/backend: "+Val(h,"backend","unavailable"));lines.Add("Database: "+Val(h,"database","unavailable"));lines.Add("Bot: "+Val(h,"bot","unavailable"));lines.Add("Scheduler: "+Val(h,"scheduler","unavailable"));lines.Add("Discord: "+Val(h,"discord","unavailable"));
            var ai=h.ContainsKey("ai")?h["ai"] as Dictionary<string,object>:null;lines.Add("Local AI: "+Val(ai,"status","unavailable"));
            var f=new Form{Text="HEX ALERT Technical Details",Size=new Size(820,520),StartPosition=FormStartPosition.CenterParent,BackColor=Color.FromArgb(10,19,32)};var box=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.FromArgb(12,22,35),ForeColor=Color.FromArgb(215,229,246),Font=new Font("Consolas",10),Text=Redact(String.Join(Environment.NewLine,lines))};f.Controls.Add(box);f.Show(this);
        }
        private void EnsureConfig(){var env=Path.Combine(root,".env");if(File.Exists(env))return;var example=Path.Combine(root,".env.example");if(!File.Exists(example))throw new Exception("Configuration template .env.example is missing.");byte[] b=new byte[64];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(b);string pw=Convert.ToBase64String(b).TrimEnd('=').Replace('+','A').Replace('/','B');using(var rng=RandomNumberGenerator.Create())rng.GetBytes(b);string dash=Convert.ToBase64String(b).TrimEnd('=').Replace('+','A').Replace('/','B');using(var rng=RandomNumberGenerator.Create())rng.GetBytes(b);string sess=Convert.ToBase64String(b).TrimEnd('=').Replace('+','A').Replace('/','B');string t=File.ReadAllText(example).Replace("POSTGRES_PASSWORD=change-me","POSTGRES_PASSWORD="+pw).Replace("hexalert:change-me@db","hexalert:"+pw+"@db").Replace("DASHBOARD_API_KEY=replace-with-a-long-random-value","DASHBOARD_API_KEY="+dash).Replace("SESSION_SECRET=replace-with-a-different-long-random-value","SESSION_SECRET="+sess);if(Regex.IsMatch(t,@"(?im)^TEST_MODE=.*$"))t=Regex.Replace(t,@"(?im)^TEST_MODE=.*$","TEST_MODE=true");else t+="\nTEST_MODE=true\n";File.WriteAllText(env,t,new UTF8Encoding(false));}
        private bool IsPortBusy(){try{using(var c=new System.Net.Sockets.TcpClient()){var t=c.ConnectAsync("127.0.0.1",8080);return t.Wait(400)&&t.Status==TaskStatus.RanToCompletion;}}catch{return false;}}
        private string Redact(string s){if(s==null)return "";s=Regex.Replace(s,@"(?im)^(\s*(?:DISCORD_TOKEN|OPENAI_API_KEY|GEMINI_API_KEY|GROQ_API_KEY|SESSION_SECRET|DASHBOARD_API_KEY|POSTGRES_PASSWORD|DATABASE_URL|AI_ENCRYPTION_KEY)\s*[=:]\s*).+$","$1[REDACTED]");s=Regex.Replace(s,@"(?i)(\b(?:token|api[_ -]?key|secret|password)\b\s*[=:]\s*)[^\s,;]+","$1[REDACTED]");s=Regex.Replace(s,@"(?i)Bot\s+[A-Za-z0-9._-]{20,}","Bot [REDACTED]");return Regex.Replace(s,@"sk-[A-Za-z0-9_-]{16,}","[REDACTED_KEY]");}
        private bool StartupEnabled(){try{using(var k=Registry.CurrentUser.OpenSubKey(RunKey)){var v=k==null?null:k.GetValue(RunValue) as string;return v!=null&&v.IndexOf("--start",StringComparison.OrdinalIgnoreCase)>=0;}}catch{return false;}}
        private void SetStartup(bool on){try{using(var k=Registry.CurrentUser.CreateSubKey(RunKey)){if(on)k.SetValue(RunValue,"\""+Application.ExecutablePath+"\" --start");else k.DeleteValue(RunValue,false);}message.Text="Current-user Windows startup updated.";}catch(Exception e){MessageBox.Show(Redact(e.Message),"Startup setting");}}
        protected override void OnFormClosing(FormClosingEventArgs e){if(allowClose){base.OnFormClosing(e);return;}if(minimizeToTray&&tray.Visible){e.Cancel=true;Hide();tray.ShowBalloonTip(2000,"HEX ALERT","Control Center minimized. Services continue running.",ToolTipIcon.Info);return;}e.Cancel=true;ExitApp();}
        private void ExitApp(){var r=MessageBox.Show(this,"Stop HEX ALERT services before exiting?\n\nYes: Stop services and exit\nNo: Exit launcher only\nCancel: Return to launcher","Exit HEX ALERT",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(r==DialogResult.Cancel)return;if(r==DialogResult.Yes){closingAfterStop=true;Operate("Stopping services…",async()=>{await Docker("compose stop",180000);return "Services stopped.";});Task.Run(async()=>{while(busy)await Task.Delay(250);if(closingAfterStop)BeginInvoke((Action)FinishExit);});return;}FinishExit();}
        private void FinishExit(){allowClose=true;poll.Stop();tray.Visible=false;Close();}
        protected override void Dispose(bool disposing){if(disposing){poll.Dispose();tray.Dispose();}base.Dispose(disposing);}
    }
